/** One pooled dense switch table. */
export type SwitchTable = {
    /** The smallest value covered by the table. */
    readonly min: bigint;
    /** The table entries. */
    readonly cases: ReadonlyArray<SwitchCase>;
};

export const SwitchTable = {
    /** Encode this value. */
    encode(writer: BinaryWriter, value: SwitchTable): void {
        encodeSwitchTable(writer, value);
    },

    /** Decode one SwitchTable. */
    decode(reader: BinaryReader): SwitchTable {
        return decodeSwitchTable(reader);
    },

    /** Return this value as JSON. */
    toJson(value: SwitchTable): Json {
        return toJsonSwitchTable(value);
    },

    /** Return one SwitchTable from one JSON value. */
    fromJson(value: Json): SwitchTable {
        return fromJsonSwitchTable(value);
    },
};

/** Encode one SwitchTable. */
export function encodeSwitchTable(writer: BinaryWriter, value: SwitchTable): void {
    writer.writeSigned(value.min);
    writer.writeUnsigned(value.cases.length);
    for (const item1 of value.cases) {
        encodeSwitchCase(writer, item1);
    }
}

/** Decode one SwitchTable. */
export function decodeSwitchTable(reader: BinaryReader): SwitchTable {
    const min = reader.readSigned();
    const cases = (() => { const length1 = reader.readNumber(); const items1: Array<SwitchCase> = []; for (let index = 0; index < length1; index += 1) { items1.push(decodeSwitchCase(reader)); } return items1; })();

    return {
        min,
        cases,
    };
}

/** Return one JSON value for one SwitchTable. */
export function toJsonSwitchTable(value: SwitchTable): Json {
    return {
        min: value.min.toString(),
        cases: value.cases.map((item0) => toJsonSwitchCase(item0)),
    };
}

/** Return one SwitchTable from one JSON value. */
export function fromJsonSwitchTable(value: Json): SwitchTable {
    const object = jsonObject(value);

    return {
        min: jsonBigint(jsonField(object, "min")),
        cases: jsonArray(jsonField(object, "cases")).map((item0) => fromJsonSwitchCase(item0)),
    };
}
